describe('Session Expired Message', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display session expired message when token times out', () => {
    // Setup: Intercept the API call to get user data
    cy.intercept('GET', '/api/user/data').as('getUserData');

    // First, verify the page loads successfully
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Verify initial user data is displayed
    cy.wait('@getUserData').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    });

    // Simulate token expiration by clearing session storage
    cy.window().then((win) => {
      win.sessionStorage.clear();
    });

    // Verify session expired message appears
    cy.get('[data-testid="session-expired-message"]').should('be.visible');
    cy.get('[data-testid="session-expired-message"]').should('contain', 'Your session has expired');

    // Verify login button is visible for re-authentication
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify error state styles are applied
    cy.get('[data-testid="session-expired-message"]').should('have.css', 'color', 'red');

    // Verify user is redirected to login page
    cy.url().should('include', '/login');
  });

  it('should not display session expired message when token is still valid', () => {
    // Setup: Intercept the API call to get user data
    cy.intercept('GET', '/api/user/data').as('getUserData');

    // Verify page loads successfully
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Verify initial user data is displayed
    cy.wait('@getUserData').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      cy.get('[data-testid="user-name"]').should('contain', 'Jane Smith');
    });

    // Simulate token renewal by setting a valid session token
    cy.window().then((win) => {
      win.sessionStorage.setItem('token', 'valid-token-value');
    });

    // Verify session expired message is not displayed
    cy.get('[data-testid="session-expired-message"]').should('not.exist');

    // Verify user can still interact with the page
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', 'Jane Smith');

    // Verify no error state styles are applied
    cy.get('[data-testid="session-expired-message"]').should('not.have.css', 'color', 'red');
  });
});
